  logic prev_m_aw_valid, prev_m_aw_ready;
  aw_t  prev_m_aw_pay;
  logic prev_m_w_valid, prev_m_w_ready;
  w_t   prev_m_w_pay;
  logic prev_m_ar_valid, prev_m_ar_ready;
  ar_t  prev_m_ar_pay;
  logic prev_s_b_valid, prev_s_b_ready;
  b_t   prev_s_b_pay;
  logic prev_s_r_valid, prev_s_r_ready;
  r_t   prev_s_r_pay;

  function automatic aw_t pack_m_aw();
    aw_t r;
    r.id = m_awid; r.addr = m_awaddr; r.len = m_awlen; r.size = m_awsize;
    r.burst = m_awburst; r.lock = m_awlock; r.cache = m_awcache;
    r.prot = m_awprot; r.qos = m_awqos; r.region = m_awregion;
    r.atop = m_awatop; r.user = m_awuser;
    return r;
  endfunction

  function automatic w_t pack_m_w();
    w_t r;
    r.data = m_wdata; r.strb = m_wstrb; r.is_last = m_wlast; r.user = m_wuser;
    return r;
  endfunction

  function automatic ar_t pack_m_ar();
    ar_t r;
    r.id = m_arid; r.addr = m_araddr; r.len = m_arlen; r.size = m_arsize;
    r.burst = m_arburst; r.lock = m_arlock; r.cache = m_arcache;
    r.prot = m_arprot; r.qos = m_arqos; r.region = m_arregion; r.user = m_aruser;
    return r;
  endfunction

  function automatic b_t pack_m_b();
    b_t r;
    r.id = m_bid; r.resp = m_bresp; r.user = m_buser;
    return r;
  endfunction

  function automatic r_t pack_m_r();
    r_t r;
    r.id = m_rid; r.data = m_rdata; r.resp = m_rresp;
    r.is_last = m_rlast; r.user = m_ruser;
    return r;
  endfunction

  function automatic b_t pack_s_b();
    b_t r;
    r.id = s_bid; r.resp = s_bresp; r.user = s_buser;
    return r;
  endfunction

  function automatic r_t pack_s_r();
    r_t r;
    r.id = s_rid; r.data = s_rdata; r.resp = s_rresp;
    r.is_last = s_rlast; r.user = s_ruser;
    return r;
  endfunction

  task automatic fail_msg(input string msg);
    $display("FAIL: %s", msg);
    err_cnt = err_cnt + 1;
  endtask

  task automatic clear_obs();
    m_aw_obs.delete();
    m_w_obs.delete();
    m_ar_obs.delete();
    m_b_obs.delete();
    m_r_obs.delete();
    s_b_obs.delete();
    s_r_obs.delete();
  endtask

  task automatic clear_exp();
    exp_n = 0;
  endtask

  task automatic add_exp(input int id, input int len, input bit has_r);
    exp_ids[exp_n] = id;
    exp_lens[exp_n] = len;
    exp_has_r[exp_n] = has_r;
    exp_n = exp_n + 1;
  endtask

  task automatic init_test();
    bfm_reset(5);
    clear_obs();
    clear_exp();
    bfm_bq_id.delete(); bfm_bq_t.delete();
    bfm_rq_id.delete(); bfm_rq_n.delete();
    @(negedge clk);
    s_awvalid = 1'b0; s_wvalid = 1'b0; s_arvalid = 1'b0;
    s_bready = 1'b1; s_rready = 1'b1;
    chk_b_passthru = 1'b0;
    chk_r_passthru = 1'b0;
    bfm_b_resp = 2'b00;
    bfm_b_user = 1'b0;
    bfm_r_resp = 2'b00;
    bfm_r_user = 1'b0;
    bfm_b_lag = 0;
  endtask

  task automatic offer_aw_full(
    input logic [3:0] id, input logic [31:0] addr, input logic [7:0] len,
    input logic [2:0] size, input logic [1:0] burst, input logic lock,
    input logic [3:0] cache, input logic [2:0] prot, input logic [3:0] qos,
    input logic [3:0] region, input logic [5:0] atop, input logic user,
    input int timeout, output bit accepted);
