    @(negedge clk);
    s_awid = id; s_awaddr = addr; s_awlen = len; s_awsize = size;
    s_awburst = burst; s_awlock = lock; s_awcache = cache;
    s_awprot = prot; s_awqos = qos; s_awregion = region;
    s_awatop = atop; s_awuser = user; s_awvalid = 1'b1;
    accepted = 1'b0;
    for (t = 0; t < timeout; t++) begin
      @(posedge clk);
      if (s_awready) begin accepted = 1'b1; break; end
    end
    @(negedge clk) s_awvalid = 1'b0;
  endtask

