  task automatic wait_m_aw_count(input int count, input int timeout, output bit ok);
    int t;
    ok = 1'b0;
    for (t = 0; t < timeout; t++) begin
      @(negedge clk);
      if (m_aw_obs.size() >= count) begin ok = 1'b1; break; end
    end
