  task automatic wait_s_b_count(input int count, input int timeout, output bit ok);
    int t;
    ok = 1'b0;
    for (t = 0; t < timeout; t++) begin
      @(negedge clk);
      if (s_b_obs.size() >= count) begin ok = 1'b1; break; end
    end
  endtask

  task automatic wait_s_r_count(input int count, input int timeout, output bit ok);
    int t;
    ok = 1'b0;
    for (t = 0; t < timeout; t++) begin
      @(negedge clk);
      if (s_r_obs.size() >= count) begin ok = 1'b1; break; end
    end
  endtask

  task automatic check_filtered_resp();
    int i;
    int bcnt[16];
    int rcnt[16];
    int rtot[16];
    b_t b;
    r_t r;

    for (i = 0; i < 16; i++) begin
      bcnt[i] = 0;
      rcnt[i] = 0;
      rtot[i] = 0;
    end

    for (i = 0; i < exp_n; i++) begin
      rtot[exp_ids[i]] = exp_has_r[i] ? (exp_lens[i] + 1) : 0;
    end

    if (s_b_obs.size() != exp_n)
      fail_msg("F3: wrong number of manufactured B responses");

    for (i = 0; i < s_b_obs.size(); i++) begin
      b = s_b_obs[i];
      if (b.resp !== 2'b10)
        fail_msg("F3: manufactured B resp is not SLVERR");
      if (b.id >= 16)
        fail_msg("F3: B id out of range");
      else
        bcnt[b.id] = bcnt[b.id] + 1;
    end

    for (i = 0; i < exp_n; i++) begin
      if (bcnt[exp_ids[i]] != 1)
        fail_msg("F3: filtered write did not get exactly one B");
    end

    for (i = 0; i < s_r_obs.size(); i++) begin
      r = s_r_obs[i];
      if (r.resp !== 2'b10)
        fail_msg("F4: manufactured R resp is not SLVERR");
      if (r.id >= 16)
        fail_msg("F4: R id out of range");
      else begin
        if (rtot[r.id] == 0)
          fail_msg("F5: unexpected R for write that owes none");
        else begin
          if (r.is_last !== (rcnt[r.id] == (rtot[r.id] - 1)))
            fail_msg("F4: rlast is wrong");
          rcnt[r.id] = rcnt[r.id] + 1;
        end
      end
    end

    for (i = 0; i < exp_n; i++) begin
      if (exp_has_r[i]) begin
        if (rcnt[exp_ids[i]] != rtot[exp_ids[i]])
          fail_msg("F4: wrong number of manufactured R beats");
      end else begin
        if (rcnt[exp_ids[i]] != 0)
          fail_msg("F5: R beats for non-R atomic write");
      end
    end
  endtask

  // ---------------------------------------------------------------------------
  // Monitors
  // ---------------------------------------------------------------------------
  always @(posedge clk) begin
    if (rst_n) begin
      if (m_awvalid && m_awready) m_aw_obs.push_back(pack_m_aw());
      if (m_wvalid  && m_wready)  m_w_obs.push_back(pack_m_w());
      if (m_arvalid && m_arready) m_ar_obs.push_back(pack_m_ar());
      if (m_bvalid  && m_bready)  m_b_obs.push_back(pack_m_b());
      if (m_rvalid  && m_rready)  m_r_obs.push_back(pack_m_r());
      if (s_bvalid  && s_bready)  s_b_obs.push_back(pack_s_b());
      if (s_rvalid  && s_rready)  s_r_obs.push_back(pack_s_r());
    end
  end

  always @(posedge clk) begin
    if (!rst_n) begin
      prev_m_aw_valid = 1'b0; prev_m_aw_ready = 1'b0; prev_m_aw_pay = '0;
      prev_m_w_valid  = 1'b0; prev_m_w_ready  = 1'b0; prev_m_w_pay  = '0;
      prev_m_ar_valid = 1'b0; prev_m_ar_ready = 1'b0; prev_m_ar_pay = '0;
      prev_s_b_valid  = 1'b0; prev_s_b_ready  = 1'b0; prev_s_b_pay  = '0;
      prev_s_r_valid  = 1'b0; prev_s_r_ready  = 1'b0; prev_s_r_pay  = '0;
    end else begin
      if (prev_m_aw_valid && !prev_m_aw_ready) begin
        if (!m_awvalid) fail_msg("X3: m_awvalid dropped before ready");
        else if (pack_m_aw() != prev_m_aw_pay) fail_msg("X3: m_aw payload changed");
      end
      if (prev_m_w_valid && !prev_m_w_ready) begin
        if (!m_wvalid) fail_msg("X3: m_wvalid dropped before ready");
        else if (pack_m_w() != prev_m_w_pay) fail_msg("X3: m_w payload changed");
      end
      if (prev_m_ar_valid && !prev_m_ar_ready) begin
        if (!m_arvalid) fail_msg("X3: m_arvalid dropped before ready");
        else if (pack_m_ar() != prev_m_ar_pay) fail_msg("X3: m_ar payload changed");
      end
      if (prev_s_b_valid && !prev_s_b_ready) begin
        if (!s_bvalid) fail_msg("X3: s_bvalid dropped before ready");
        else if (pack_s_b() != prev_s_b_pay) fail_msg("X3: s_b payload changed");
      end
      if (prev_s_r_valid && !prev_s_r_ready) begin
        if (!s_rvalid) fail_msg("X3: s_rvalid dropped before ready");
        else if (pack_s_r() != prev_s_r_pay) fail_msg("X3: s_r payload changed");
      end

      prev_m_aw_valid = m_awvalid; prev_m_aw_ready = m_awready; prev_m_aw_pay = pack_m_aw();
      prev_m_w_valid  = m_wvalid;  prev_m_w_ready  = m_wready;  prev_m_w_pay  = pack_m_w();
      prev_m_ar_valid = m_arvalid; prev_m_ar_ready = m_arready; prev_m_ar_pay = pack_m_ar();
      prev_s_b_valid  = s_bvalid;  prev_s_b_ready  = s_bready;  prev_s_b_pay  = pack_s_b();
      prev_s_r_valid  = s_rvalid;  prev_s_r_ready  = s_rready;  prev_s_r_pay  = pack_s_r();
    end
  end

  always @(posedge clk) begin
    if (!rst_n) begin
      if (m_awvalid !== 1'b0) fail_msg("X1: m_awvalid high during reset");
      if (m_wvalid  !== 1'b0) fail_msg("X1: m_wvalid high during reset");
      if (s_bvalid !== m_bvalid) fail_msg("X1: s_bvalid not following m_bvalid during reset");
      if (s_rvalid !== m_rvalid) fail_msg("X1: s_rvalid not following m_rvalid during reset");
      if (m_bvalid) begin
        if (s_bid !== m_bid || s_bresp !== m_bresp || s_buser !== m_buser)
          fail_msg("X1/P4: B payload not passed during reset");
      end
      if (m_rvalid) begin
        if (s_rid !== m_rid || s_rdata !== m_rdata || s_rresp !== m_rresp ||
            s_rlast !== m_rlast || s_ruser !== m_ruser)
          fail_msg("X1/P3: R payload not passed during reset");
      end
    end
  end

  always @(posedge clk) begin
    if (rst_n && m_awvalid && (m_awatop !== 6'b000000))
      fail_msg("F1: m_awatop_o not zero while m_awvalid_o is high");
  end

  always @(posedge clk) begin
    if (!rst_n) begin
      debt = 0;
    end else begin
      if (m_awvalid && m_awready) debt = debt + 1;
      if (m_wvalid && m_wready && m_wlast) debt = debt - 1;
      if (debt > 4) fail_msg("W2: downstream write debt exceeded MAX_WRITE_TXNS");
    end
  end

  always @(posedge clk) begin
    if (rst_n && chk_b_passthru) begin
      if (s_bvalid !== m_bvalid)
        fail_msg("X1/P4: s_bvalid does not follow m_bvalid");
      if (m_bvalid) begin
        if (s_bid !== m_bid || s_bresp !== m_bresp || s_buser !== m_buser)
          fail_msg("P4: B response not returned unmodified");
      end
    end
    if (rst_n && chk_r_passthru) begin
      if (s_rvalid !== m_rvalid)
        fail_msg("X1/P3: s_rvalid does not follow m_rvalid");
      if (m_rvalid) begin
        if (s_rid !== m_rid || s_rdata !== m_rdata || s_rresp !== m_rresp ||
            s_rlast !== m_rlast || s_ruser !== m_ruser)
          fail_msg("P3: R response not returned unmodified");
      end
    end
  end

  // ---------------------------------------------------------------------------
  // Directed tests
  // ---------------------------------------------------------------------------
  task automatic test_nonatomic();
    bit ok, acc;
    aw_t exp_aw;
    w_t  exp_w;
    int i;

    init_test();
    bfm_b_lag = 1;
    bfm_b_resp = 2'b11;
    bfm_b_user = 1'b1;
    chk_b_passthru = 1'b1;

    offer_aw_full(4'h5, 32'h1234_5678, 8'd2, 3'd2, 2'd1, 1'b0,
                  4'hA, 3'h3, 4'h9, 4'hC, 6'b000001, 1'b1, 200, acc);
    if (!acc) begin fail_msg("P1/X4: non-atomic AW not accepted"); return; end

    wait_m_aw_count(1, 200, ok);
    if (!ok) begin fail_msg("P1: non-atomic AW not forwarded"); return; end

    exp_aw.id = 4'h5; exp_aw.addr = 32'h1234_5678; exp_aw.len = 8'd2;
    exp_aw.size = 3'd2; exp_aw.burst = 2'd1; exp_aw.lock = 1'b0;
    exp_aw.cache = 4'hA; exp_aw.prot = 3'h3; exp_aw.qos = 4'h9;
    exp_aw.region = 4'hC; exp_aw.atop = 6'b000000; exp_aw.user = 1'b1;
    if (m_aw_obs[0] != exp_aw)
      fail_msg("P1: non-atomic AW fields not forwarded unmodified");

    for (i = 0; i < 3; i++) begin
      offer_w_full(32'hA000_0000 + i, 4'hF - 4'(i), (i == 2), 1'b1, 200, acc);
      if (!acc) begin fail_msg("P2/X4: non-atomic W beat not accepted"); return; end
    end

    wait_m_w_count(3, 200, ok);
    if (!ok) begin fail_msg("P2: non-atomic W beats not forwarded"); return; end

    for (i = 0; i < 3; i++) begin
      exp_w.data = 32'hA000_0000 + i;
      exp_w.strb = 4'hF - 4'(i);
      exp_w.is_last = (i == 2);
      exp_w.user = 1'b1;
      if (m_w_obs[i] != exp_w)
        fail_msg("P2: W beat not forwarded unmodified");
    end

    wait_s_b_count(1, 200, ok);
    if (!ok) begin fail_msg("P4: non-atomic B not returned"); return; end

    if (s_b_obs[0].id !== 4'h5) fail_msg("P4: B id not unmodified");
    if (s_b_obs[0].resp !== 2'b11) fail_msg("P4: B resp not unmodified");
    if (s_b_obs[0].user !== 1'b1) fail_msg("P4: B user not unmodified");
    if (s_b_obs.size() != 1) fail_msg("P4: unexpected extra B responses");

    chk_b_passthru = 1'b0;
  endtask

  task automatic test_filtered_multi();
    bit ok, acc;
    int i;

    init_test();
    bfm_b_lag = 2;
    clear_exp();

    // Write A: id=1, len=2, atop[5:4]=10, owes R
    add_exp(1, 2, 1);
    offer_aw_full(4'h1, 32'h1000, 8'd2, 3'd2, 2'd1, 1'b0,
                  4'h0, 3'h0, 4'h0, 4'h0, 6'b100001, 1'b0, 200, acc);
    if (!acc) begin fail_msg("F1/X4: filtered AW A not accepted"); return; end
    for (i = 0; i < 3; i++) begin
      offer_w_full(32'hB000_0000 + i, 4'hF, (i == 2), 1'b0, 200, acc);
      if (!acc) begin fail_msg("F2/X4: filtered W A not consumed"); return; end
    end

    // Write B: id=2, len=0, atop[5:4]=01, no R
    add_exp(2, 0, 0);
    offer_aw_full(4'h2, 32'h2000, 8'd0, 3'd2, 2'd1, 1'b0,
                  4'h0, 3'h0, 4'h0, 4'h0, 6'b010001, 1'b0, 200, acc);
    if (!acc) begin fail_msg("F1/X4: filtered AW B not accepted"); return; end
    offer_w_full(32'hB100_0000, 4'hF, 1'b1, 1'b0, 200, acc);
    if (!acc) begin fail_msg("F2/X4: filtered W B not consumed"); return; end

    // Write C: id=3, len=1, atop[5:4]=11, owes R
    add_exp(3, 1, 1);
    offer_aw_full(4'h3, 32'h3000, 8'd1, 3'd2, 2'd1, 1'b0,
                  4'h0, 3'h0, 4'h0, 4'h0, 6'b110001, 1'b0, 200, acc);
    if (!acc) begin fail_msg("F1/X4: filtered AW C not accepted"); return; end
    for (i = 0; i < 2; i++) begin
      offer_w_full(32'hB200_0000 + i, 4'hF, (i == 1), 1'b0, 200, acc);
      if (!acc) begin fail_msg("F2/X4: filtered W C not consumed"); return; end
    end

    wait_s_b_count(3, 200, ok);
    if (!ok) begin fail_msg("F3/X4: manufactured B responses not completed"); return; end
    wait_s_r_count(5, 200, ok);
    if (!ok) begin fail_msg("F4/X4: manufactured R responses not completed"); return; end

    if (m_aw_obs.size() != 0) fail_msg("F1: atomic AW was forwarded");
    if (m_w_obs.size() != 0) fail_msg("F2: filtered W was forwarded");

    check_filtered_resp();
  endtask

  task automatic test_bound();
    bit ok, acc, acc5;
    int i;

    init_test();
    bfm_b_lag = 0;

    for (i = 0; i < 4; i++) begin
      offer_aw_full(4'(i), 32'h4000 + i, 8'd0, 3'd2, 2'd1, 1'b0,
                    4'h0, 3'h0, 4'h0, 4'h0, 6'b000000, 1'b0, 200, acc);
      if (!acc) begin fail_msg("W3/X4: non-atomic AW stalled below bound"); return; end
    end

    wait_m_aw_count(4, 200, ok);
    if (!ok) begin fail_msg("P1/W3: first 4 non-atomic AWs not forwarded"); return; end

    offer_aw_full(4'h4, 32'h4004, 8'd0, 3'd2, 2'd1, 1'b0,
                  4'h0, 3'h0, 4'h0, 4'h0, 6'b000000, 1'b0, 20, acc5);

    repeat (20) @(negedge clk);

    offer_w_full(32'hC000_0000, 4'hF, 1'b1, 1'b0, 200, acc);
    if (!acc) begin fail_msg("W4/X4: W0 not accepted"); return; end
    wait_m_w_count(1, 200, ok);
    if (!ok) begin fail_msg("W4: W0 not forwarded"); return; end

    if (!acc5) begin
      offer_aw_full(4'h4, 32'h4004, 8'd0, 3'd2, 2'd1, 1'b0,
                    4'h0, 3'h0, 4'h0, 4'h0, 6'b000000, 1'b0, 200, acc);
      if (!acc) begin fail_msg("W3/X4: 5th AW not accepted after debt reduced"); return; end
    end

    for (i = 1; i < 5; i++) begin
      offer_w_full(32'hC000_0000 + i, 4'hF, 1'b1, 1'b0, 200, acc);
      if (!acc) begin fail_msg("W4/X4: W beat not accepted"); return; end
    end

    wait_m_w_count(5, 200, ok);
    if (!ok) begin fail_msg("W4: not all W beats forwarded"); return; end
    wait_s_b_count(5, 200, ok);
    if (!ok) begin fail_msg("P4/W4: not all B responses returned"); return; end

    for (i = 0; i < 5; i++) begin
      if (m_aw_obs[i].id !== 4'(i))
        fail_msg("P1/W4: AW forwarded out of order or wrong ID");
    end
    for (i = 0; i < 5; i++) begin
      if (s_b_obs[i].id !== 4'(i))
        fail_msg("P4/W4: B response ID mismatch");
    end

    if (m_aw_obs.size() != 5) fail_msg("W2: unexpected number of forwarded AWs");
    if (m_w_obs.size() != 5) fail_msg("W4: unexpected number of forwarded W beats");
  endtask

